/**
 * Rate-limited to 30 messages / minute / (user, trip). Returns 429 with
a `Retry-After` header when exceeded. Recipient receives a realtime
`trip:message` socket event and (when offline / not in chat) a push.

 * @summary Send a chat message in an active trip.
 */
export const CreateTripMessageParams = zod.object({
  tripId: zod.coerce.string().uuid(),
});

export const createTripMessageBodyContentMax = 4000;

export const createTripMessageBodyAudioDurationMsMax = 120000;

export const createTripMessageBodyClientIdMax = 64;

export const CreateTripMessageBody = zod.object({
  type: zod.enum(["text", "image", "voice"]),
  content: zod.string().min(1).max(createTripMessageBodyContentMax),
  audioDurationMs: zod
    .number()
    .min(1)
    .max(createTripMessageBodyAudioDurationMsMax)
    .nullish()
    .describe("Required for voice messages. Max 120000ms (2 minutes)."),
  clientId: zod.string().max(createTripMessageBodyClientIdMax).nullish(),
});

export const CreateTripMessageResponse = zod.object({
  message: zod.object({
    id: zod.string().uuid(),
    tripId: zod.string().uuid(),
    senderId: zod.string().uuid(),
    type: zod.enum(["text", "image", "voice"]),
    content: zod
      .string()
      .describe(
        "Plain text, or `\/objects\/...` path for image\/voice attachments.",
      ),
    audioDurationMs: zod
      .number()
      .min(1)
      .nullish()
      .describe("Duration in milliseconds for voice messages."),
    deliveredAt: zod.coerce
      .date()
      .nullish()
      .describe("When the recipient's client confirmed delivery (✓✓ grey)."),
    readAt: zod.coerce
      .date()
      .nullish()
      .describe("When the recipient marked the message as read (✓✓ blue)."),
    createdAt: zod.coerce.date(),
    senderFirstName: zod.string().nullish(),
    senderLastName: zod.string().nullish(),
    clientId: zod
      .string()
      .nullish()
      .describe("Client-supplied id for optimistic-send reconciliation."),
  }),
});

