/**
 * Marks every message sent by the peer up to and including
`upToMessageId` (or all if omitted) as read. Emits `chat:message:read`
to the sender (✓✓ blue) and `chat:unread:update` with the actual
remaining unread count for the caller.

 * @summary Mark peer messages in a trip as read (and delivered).
 */
export const MarkTripMessagesReadParams = zod.object({
  tripId: zod.coerce.string().uuid(),
});

export const MarkTripMessagesReadBody = zod.object({
  upToMessageId: zod
    .string()
    .uuid()
    .nullish()
    .describe(
      "If set, only mark messages with `createdAt <= this message's\ncreatedAt` as read. Omit to mark all peer messages as read.\n",
    ),
});

export const markTripMessagesReadResponseUpdatedMin = 0;

export const markTripMessagesReadResponseUnreadMin = 0;

export const MarkTripMessagesReadResponse = zod.object({
  updated: zod.number().min(markTripMessagesReadResponseUpdatedMin),
  messageIds: zod.array(zod.string().uuid()),
  unread: zod
    .number()
    .min(markTripMessagesReadResponseUnreadMin)
    .describe(
      "Remaining unread peer messages for the caller after this update.",
    ),
});

