export const updateMyQuickRepliesBodyRepliesMax = 12;

export const UpdateMyQuickRepliesBody = zod.object({
  role: zod.enum(["driver", "rider"]),
  replies: zod
    .array(zod.string().min(1).max(updateMyQuickRepliesBodyRepliesItemMax))
    .max(updateMyQuickRepliesBodyRepliesMax),
});

export const updateMyQuickRepliesResponseDriverItemMax = 60;

export const updateMyQuickRepliesResponseDriverMax = 12;

export const updateMyQuickRepliesResponseRiderItemMax = 60;

export const updateMyQuickRepliesResponseRiderMax = 12;

export const UpdateMyQuickRepliesResponse = zod.object({
  driver: zod
    .array(zod.string().min(1).max(updateMyQuickRepliesResponseDriverItemMax))
    .max(updateMyQuickRepliesResponseDriverMax)
    .describe(
      "Saved quick-reply phrases for the driver chat side. Empty when the user has not customised this side.",
    ),
  rider: zod
    .array(zod.string().min(1).max(updateMyQuickRepliesResponseRiderItemMax))
    .max(updateMyQuickRepliesResponseRiderMax)
    .describe(
      "Saved quick-reply phrases for the rider chat side. Empty when the user has not customised this side.",
    ),
});

